import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'aevko-attachment',
  standalone: true,
  templateUrl: './attachment.component.html',
  styleUrl: './attachment.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoAttachment {
  readonly name = input.required<string>();
  readonly metadata = input<string>();
}

:host {
  align-items: center;
  border: 1px solid var(--aevko-border, #e4e4e7);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: auto 1fr auto;
  padding: 0.75rem;
}
.visual {
  align-items: center;
  display: inline-flex;
  line-height: 0;
}
.visual:empty {
  display: none;
}
.copy {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}
.copy strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.copy small {
  color: var(--aevko-muted, #71717a);
}
.actions {
  align-items: center;
  display: inline-flex;
  gap: 0.5rem;
}
